//! The public per-curve API (`p256`, `p384`), generated by one macro.

/// Generates `SecretKey`, `PublicKey` and `Signature` for a curve.
macro_rules! curve_api {
    ($curve:ty, $l:literal, $len:literal, $hash:ty, $name:literal) => {
        use crate::Error;
        use crate::ec::{self, Point, Scalar};
        use crate::hash::Hash;

        type C = $curve;

        /// The length of a scalar, a coordinate and each half of a fixed-width signature.
        pub const SCALAR_LEN: usize = $len;

        #[doc = concat!("A ", $name, " private key: a scalar in `[1, n)`, for ECDH and ECDSA.")]
        #[derive(Clone)]
        pub struct SecretKey {
            d: Scalar<C, $l>,
        }

        impl std::fmt::Debug for SecretKey {
            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                f.write_str(concat!($name, " SecretKey(..)"))
            }
        }

        impl SecretKey {
            /// A new key from the operating system's randomness (rejection sampling).
            pub fn generate() -> Result<SecretKey, Error> {
                loop {
                    let b: [u8; $len] = crate::random_array()?;
                    if let Ok(k) = Self::from_bytes(&b) {
                        return Ok(k);
                    }
                }
            }

            /// From the big-endian scalar; fails with [`Error::InvalidKey`] unless it is in
            /// `[1, n)` and exactly
            #[doc = concat!(stringify!($len), " bytes long.")]
            pub fn from_bytes(b: &[u8]) -> Result<SecretKey, Error> {
                let d = Scalar::<C, $l>::from_be_bytes(b).ok_or(Error::InvalidKey)?;
                if d.is_zero() != 0 {
                    return Err(Error::InvalidKey);
                }
                Ok(SecretKey { d })
            }

            /// The big-endian scalar.
            #[must_use]
            pub fn to_bytes(&self) -> [u8; $len] {
                let mut b = [0u8; $len];
                self.d.write_be(&mut b);
                b
            }

            /// The public key `d·G`.
            #[must_use]
            pub fn public_key(&self) -> PublicKey {
                PublicKey {
                    q: Point::<C, $l>::mul_base(&self.d),
                }
            }

            /// ECDH (SEC1 §3.3.1): the x-coordinate of `d·Q`. The peer key was validated when
            /// it was decoded, and the group has prime order, so the result is never the
            /// identity.
            #[must_use]
            pub fn diffie_hellman(&self, peer: &PublicKey) -> [u8; $len] {
                let mut out = [0u8; $len];
                if let Some((x, _)) = peer.q.mul(&self.d).to_affine() {
                    x.write_be(&mut out);
                }
                out
            }

            #[doc = concat!("Signs `msg` hashed with ", stringify!($hash), " (deterministic nonce, RFC 6979).")]
            #[must_use]
            pub fn sign(&self, msg: &[u8]) -> Signature {
                self.sign_with::<$hash>(msg)
            }

            /// Signs `msg` hashed with `H` (RFC 6979 nonce with HMAC-`H`).
            #[must_use]
            pub fn sign_with<H: Hash>(&self, msg: &[u8]) -> Signature {
                self.sign_prehash::<H>(H::digest(msg).as_ref())
            }

            /// Signs a precomputed digest; `H` is the hash used for the RFC 6979 nonce (it
            /// should be the one that produced `digest`).
            #[must_use]
            pub fn sign_prehash<H: Hash>(&self, digest: &[u8]) -> Signature {
                Signature(ec::sign::<C, H, $l>(&self.d, digest))
            }
        }

        #[doc = concat!("A ", $name, " public key: a point on the curve other than the identity.")]
        #[derive(Clone)]
        pub struct PublicKey {
            q: Point<C, $l>,
        }

        impl std::fmt::Debug for PublicKey {
            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                write!(f, concat!($name, " PublicKey("))?;
                for b in self.to_uncompressed() {
                    write!(f, "{b:02x}")?;
                }
                write!(f, ")")
            }
        }

        impl PartialEq for PublicKey {
            fn eq(&self, o: &Self) -> bool {
                self.to_uncompressed() == o.to_uncompressed()
            }
        }
        impl Eq for PublicKey {}

        impl PublicKey {
            /// Decodes a SEC1 point, uncompressed (`04 || x || y`) or compressed
            /// (`02`/`03 || x`). Coordinates must be below `p` and the point on the curve;
            /// the identity is rejected.
            pub fn from_sec1(b: &[u8]) -> Result<PublicKey, Error> {
                Point::<C, $l>::from_sec1(b)
                    .map(|q| PublicKey { q })
                    .ok_or(Error::InvalidKey)
            }

            /// The uncompressed SEC1 encoding, `04 || x || y`.
            #[must_use]
            pub fn to_uncompressed(&self) -> Vec<u8> {
                self.q.to_uncompressed().unwrap_or_default()
            }

            /// The compressed SEC1 encoding, `02`/`03 || x`.
            #[must_use]
            pub fn to_compressed(&self) -> Vec<u8> {
                let mut u = self.to_uncompressed();
                let odd = u.last().map_or(0, |b| b & 1);
                u.truncate(1 + $len);
                u[0] = 2 | odd;
                u
            }

            #[doc = concat!("Verifies `sig` on `msg` hashed with ", stringify!($hash), ".")]
            pub fn verify(&self, msg: &[u8], sig: &Signature) -> Result<(), Error> {
                self.verify_with::<$hash>(msg, sig)
            }

            /// Verifies `sig` on `msg` hashed with `H`.
            pub fn verify_with<H: Hash>(&self, msg: &[u8], sig: &Signature) -> Result<(), Error> {
                self.verify_prehash(H::digest(msg).as_ref(), sig)
            }

            /// Verifies `sig` on a precomputed digest (truncated or zero-extended to the
            /// order's size as ECDSA specifies). High-`s` signatures are accepted (TLS and
            /// X.509 do not require low `s`).
            pub fn verify_prehash(&self, digest: &[u8], sig: &Signature) -> Result<(), Error> {
                ec::verify::<C, $l>(&self.q, digest, &sig.0)
            }
        }

        /// An ECDSA signature `(r, s)` with `1 <= r, s < n`.
        pub struct Signature(ec::Sig<C, $l>);

        impl Clone for Signature {
            fn clone(&self) -> Self {
                Signature(ec::Sig {
                    r: self.0.r,
                    s: self.0.s,
                })
            }
        }

        impl std::fmt::Debug for Signature {
            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                write!(f, concat!($name, " Signature("))?;
                for b in self.to_fixed() {
                    write!(f, "{b:02x}")?;
                }
                write!(f, ")")
            }
        }

        impl PartialEq for Signature {
            fn eq(&self, o: &Self) -> bool {
                self.to_fixed() == o.to_fixed()
            }
        }
        impl Eq for Signature {}

        impl Signature {
            /// From the DER `ECDSA-Sig-Value` (TLS, X.509), strictly: minimal positive
            /// INTEGERs, no trailing data. Fails with [`Error::Encoding`] or, for values out
            /// of range, [`Error::Verification`].
            pub fn from_der(b: &[u8]) -> Result<Signature, Error> {
                ec::sig_from_der::<C, $l>(b).map(Signature)
            }

            /// From the fixed-width `r || s` form (IEEE P1363, JWS, WebRTC).
            pub fn from_fixed(b: &[u8]) -> Result<Signature, Error> {
                ec::sig_from_fixed::<C, $l>(b).map(Signature)
            }

            /// The DER encoding.
            #[must_use]
            pub fn to_der(&self) -> Vec<u8> {
                ec::sig_to_der(&self.0)
            }

            /// The fixed-width `r || s` encoding.
            #[must_use]
            pub fn to_fixed(&self) -> Vec<u8> {
                let mut v = vec![0u8; 2 * $len];
                self.0.r.write_be(&mut v[..$len]);
                self.0.s.write_be(&mut v[$len..]);
                v
            }
        }
    };
}

pub(crate) use curve_api;
